const input = items[0]?.json || {};

return [
 {
   json: {
     ...input,
     narrative_config: {
       service_name: 'DALIA_M11_Narrative_Rehearsal_Runner',
       service_version: 'v1',
       environment: 'demo',

       demo: {
         title: 'DALIA Demo Lite — Vertical Slice de Ventas Conversacionales',
         target_audience: 'cliente, decisor de negocio, equipo comercial o equipo interno YoEco',
         narrative_goal: 'Demostrar que DALIA puede atender, asesorar, mostrar productos, simular compra, transferir a humano y dejar trazabilidad mínima de punta a punta.'
       },

       positioning: {
         core_message: 'DALIA no es solo un chatbot; es un sistema modular de ventas conversacionales con IA.',
         value_promises: [
           'Reducir tiempos de respuesta',
           'Acompañar al cliente durante la exploración',
           'Recomendar productos reales desde catálogo',
           'Simular un cierre comercial completo',
           'Transferir a humano sin pérdida de contexto',
           'Dejar trazabilidad para soporte y mejora continua'
         ],
         avoid_positioning: [
           'prometer automatización completa en esta demo Lite',
           'presentar pagos o envíos como reales',
           'hablar demasiado de nodos o herramientas internas',
           'mostrar la demo como una colección técnica de flujos'
         ]
       },

       rehearsal_policy: {
         max_demo_minutes: 12,
         max_intro_minutes: 2,
         max_case_minutes: 2,
         show_observability_evidence: true,
         require_fallback_plan: true,
         require_go_no_go: true
       },

       storage: {
         narrative_rehearsals_table: 'dalia_demo_narrative_rehearsals'
       }
     }
   }
 }
];

function makeId(prefix) {
 const ts = Date.now();
 const rand = Math.random().toString(36).slice(2, 8).toUpperCase();
 return `${prefix}_${ts}_${rand}`;
}

const input = items[0]?.json || {};
const config = input.narrative_config || {};
const demo = config.demo || {};

const rehearsalDraft = {
 narrative_rehearsal_id: makeId('narr_demo'),
 validation_run_id: input.validation_run?.validation_run_id || '',
 environment: config.environment || 'demo',

 status: 'draft',
 go_no_go: '',

 demo_title: demo.title || 'DALIA Demo Lite',
 target_audience: demo.target_audience || '',
 narrative_goal: demo.narrative_goal || '',

 demo_script: {},
 demo_scenes: [],
 evaluation_criteria: {},

 rehearsal_notes: [],
 findings: [],
 adjustment_backlog: [],

 presenter_checklist: [],
 fallback_plan: []
};

return [
 {
   json: {
     ...input,
     narrative_rehearsal: rehearsalDraft
   }
 }
];

const input = items[0]?.json || {};
const config = input.narrative_config || {};
const positioning = config.positioning || {};
const policy = config.rehearsal_policy || {};

const script = {
 opening: {
   title: 'Apertura',
   duration_minutes: policy.max_intro_minutes || 2,
   talk_track: [
     'Hoy vamos a ver una demo vertical de DALIA en modo Lite.',
     positioning.core_message || 'DALIA es un sistema de ventas conversacionales con IA.',
     'La idea no es mostrar una automatización perfecta de todo el negocio, sino un recorrido completo y creíble: atención, recomendación, producto, compra demo, handoff humano y trazabilidad.'
   ],
   presenter_notes: [
     'No iniciar hablando de n8n, Qdrant o nodos.',
     'Empezar por el problema de negocio: atención lenta, pérdida de oportunidades y dependencia operativa.',
     'Reforzar que es un vertical slice demostrable.'
   ]
 },

 business_context: {
   title: 'Contexto de valor',
   talk_track: [
     'El punto central es convertir conversaciones en resultados de negocio.',
     'DALIA atiende, entiende intención, recomienda desde catálogo, ejecuta acciones comerciales demo y escala a humano cuando corresponde.',
     'La demo también muestra control: memoria, trazabilidad y logs para soporte.'
   ],
   value_promises: positioning.value_promises || []
 },

 transition_to_demo: {
   title: 'Transición a demostración',
   talk_track: [
     'Vamos a recorrer cinco casos obligatorios.',
     'Cada caso prueba una parte del vertical slice y al final mostraremos evidencia de trazabilidad.',
     'Cuando algo sea simulado, como pago u orden, se dirá explícitamente.'
   ]
 },

 closing: {
   title: 'Cierre',
   talk_track: [
     'La conclusión no es que DALIA reemplaza al equipo comercial.',
     'La conclusión es que DALIA puede potenciarlo: atiende más rápido, estandariza respuestas, conserva contexto, ejecuta pasos repetibles y escala a humano cuando se necesita.',
     'La siguiente evolución sería pasar de demo Lite a integración real con stack transaccional del cliente.'
   ]
 }
};

return [
 {
   json: {
     ...input,
     demo_narrative_script: script
   }
 }
];

const input = items[0]?.json || {};

const criteria = {
 scoring_scale: {
   1: 'deficiente',
   2: 'débil',
   3: 'aceptable',
   4: 'bueno',
   5: 'listo para demo'
 },

 dimensions: [
   {
     dimension_id: 'clarity',
     name: 'Claridad',
     description: 'La audiencia entiende qué problema resuelve DALIA y qué se está demostrando.',
     minimum_score: 4
   },
   {
     dimension_id: 'business_value',
     name: 'Valor de negocio',
     description: 'La demo conecta conversación, asesoría, venta, handoff y trazabilidad con impacto comercial.',
     minimum_score: 4
   },
   {
     dimension_id: 'flow_continuity',
     name: 'Continuidad del recorrido',
     description: 'Los casos se sienten como una historia y no como pruebas aisladas.',
     minimum_score: 4
   },
   {
     dimension_id: 'visible_experience',
     name: 'Experiencia visible',
     description: 'El copy, la secuencia y el tono son naturales y adecuados.',
     minimum_score: 4
   },
   {
     dimension_id: 'technical_confidence',
     name: 'Confianza técnica',
     description: 'El presentador puede explicar qué está ocurriendo sin entrar en exceso técnico.',
     minimum_score: 3
   },
   {
     dimension_id: 'fallback_readiness',
     name: 'Preparación ante fallos',
     description: 'Existe una forma clara de continuar la demo si algo falla.',
     minimum_score: 4
   },
   {
     dimension_id: 'closing_strength',
     name: 'Cierre comercial',
     description: 'El cierre deja claro el valor, límites de la demo y próximos pasos.',
     minimum_score: 4
   }
 ],

 go_no_go_rules: {
   narrative_ready: [
     'todas las dimensiones críticas con score >= mínimo',
     'sin hallazgos críticos abiertos',
     'fallback plan definido',
     'guion de apertura y cierre listo'
   ],
   narrative_not_ready: [
     'claridad menor a 4',
     'valor de negocio menor a 4',
     'fallback no definido',
     'demo parece una revisión técnica de nodos'
   ]
 }
};

return [
 {
   json: {
     ...input,
     narrative_evaluation_criteria: criteria
   }
 }
];

const input = items[0]?.json || {};

const checklist = [
 {
   item_id: 'PREP01',
   category: 'preparación',
   text: 'Tener abiertos WhatsApp o Telegram de prueba.',
   required: true
 },
 {
   item_id: 'PREP02',
   category: 'preparación',
   text: 'Tener Supabase abierto con consulta de M8 por session_id.',
   required: true
 },
 {
   item_id: 'PREP03',
   category: 'preparación',
   text: 'Tener identificados los 5 mensajes de prueba.',
   required: true
 },
 {
   item_id: 'PREP04',
   category: 'narrativa',
   text: 'Iniciar por el problema de negocio, no por la arquitectura.',
   required: true
 },
 {
   item_id: 'PREP05',
   category: 'narrativa',
   text: 'Explicar que comercio, pago, orden y tracking son demo/simulados.',
   required: true
 },
 {
   item_id: 'PREP06',
   category: 'narrativa',
   text: 'No mencionar n8n, Qdrant, RAG, nodos o workflows salvo que la audiencia sea técnica y lo pida.',
   required: true
 },
 {
   item_id: 'PREP07',
   category: 'evidencia',
   text: 'Mostrar al menos una traza M8 con eventos ordenados.',
   required: true
 },
 {
   item_id: 'PREP08',
   category: 'cierre',
   text: 'Cerrar con valor: velocidad, estandarización, continuidad IA-humano y trazabilidad.',
   required: true
 }
];

return [
 {
   json: {
     ...input,
     presenter_checklist: checklist
   }
 }
];

const input = items[0]?.json || {};

const fallbackPlan = [
 {
   failure_scenario: 'El canal WhatsApp no responde',
   severity: 'high',
   fallback_action: 'Cambiar a Telegram o mostrar ejecución previa registrada en M8.',
   talk_track: 'El canal externo puede fallar; lo importante es que la arquitectura deja trazabilidad y permite degradar el canal.'
 },
 {
   failure_scenario: 'No aparece imagen del producto',
   severity: 'medium',
   fallback_action: 'Usar el mensaje fallback de imagen y mostrar que M7 registró el evento o error.',
   talk_track: 'El sistema no inventa imágenes; si no hay repositorio disponible, responde de forma controlada.'
 },
 {
   failure_scenario: 'La recomendación no encuentra producto',
   severity: 'high',
   fallback_action: 'Mostrar fallback de catálogo y explicar que el catálogo es fuente de verdad.',
   talk_track: 'DALIA prefiere decir que no tiene información antes que inventar productos.'
 },
 {
   failure_scenario: 'Falla comercio demo',
   severity: 'high',
   fallback_action: 'Mostrar transaction_id hasta el estado alcanzado y revisar logs M8.',
   talk_track: 'La cadena transaccional es verificable por estado; si falla, se diagnostica por paso.'
 },
 {
   failure_scenario: 'Falla handoff humano',
   severity: 'high',
   fallback_action: 'Mostrar handoff_id, estado failed/human_notified y error_reason.',
   talk_track: 'El valor del handoff es conservar contexto y saber si el humano fue notificado.'
 },
 {
   failure_scenario: 'Faltan logs de M8',
   severity: 'high',
   fallback_action: 'No continuar con demo como si nada; marcar hallazgo de observabilidad.',
   talk_track: 'Sin observabilidad no hay soporte confiable. Esta demo justamente valida que todo sea trazable.'
 }
];

return [
 {
   json: {
     ...input,
     demo_fallback_plan: fallbackPlan
   }
 }
];

const input = items[0]?.json || {};

const script = input.demo_script || input.demo_narrative_script || {};
const scenes = input.demo_scenes || input.demo_commercial_scenes || [];
const criteria = input.evaluation_criteria || input.narrative_evaluation_criteria || {};
const checklist = input.presenter_checklist || [];
const fallbackPlan = input.fallback_plan || input.demo_fallback_plan || [];

const findings = [];
const warnings = [];

if (!script.opening || !script.closing) {
 findings.push({
   severity: 'failed',
   code: 'missing_opening_or_closing_script',
   detail: 'El guion debe tener apertura y cierre.'
 });
}

if (!Array.isArray(scenes) || scenes.length < 5) {
 findings.push({
   severity: 'failed',
   code: 'missing_demo_scenes',
   detail: 'Debe haber al menos 5 escenas alineadas a los casos obligatorios.'
 });
}

const requiredCases = ['UC01', 'UC02', 'UC03', 'UC04', 'UC05'];
const linkedCases = scenes.map(scene => scene.linked_case_id);

const missingCases = requiredCases.filter(caseId => !linkedCases.includes(caseId));

if (missingCases.length > 0) {
 findings.push({
   severity: 'failed',
   code: 'missing_required_case_scene',
   detail: missingCases
 });
}

if (!criteria.dimensions || criteria.dimensions.length === 0) {
 findings.push({
   severity: 'failed',
   code: 'missing_narrative_evaluation_criteria',
   detail: 'No hay criterios de evaluación narrativa.'
 });
}

if (!Array.isArray(checklist) || checklist.length === 0) {
 warnings.push({
   code: 'missing_presenter_checklist',
   detail: 'No hay checklist del presentador.'
 });
}

if (!Array.isArray(fallbackPlan) || fallbackPlan.length === 0) {
 findings.push({
   severity: 'failed',
   code: 'missing_fallback_plan',
   detail: 'No hay plan de fallback para la demo.'
 });
}

const hasFailure = findings.some(f => f.severity === 'failed');
const status = hasFailure
 ? 'narrative_not_ready'
 : warnings.length > 0
   ? 'rehearsed'
   : 'narrative_ready';

const goNoGo = status === 'narrative_ready'
 ? 'GO_NARRATIVE'
 : status === 'rehearsed'
   ? 'GO_NARRATIVE_WITH_WARNINGS'
   : 'NO_GO_NARRATIVE';

const adjustmentBacklog = [
 ...findings.map(finding => ({
   target: 'narrative_script',
   priority: 'high',
   action: `Corregir hallazgo narrativo: ${finding.code}`,
   detail: finding.detail
 })),
 ...warnings.map(warning => ({
   target: 'narrative_script',
   priority: 'medium',
   action: `Revisar advertencia narrativa: ${warning.code}`,
   detail: warning.detail
 }))
];

return [
 {
   json: {
     ...input,
     narrative_readiness: {
       status,
       go_no_go: goNoGo,
       findings,
       warnings,
       adjustment_backlog: adjustmentBacklog,
       evaluated_at: new Date().toISOString()
     }
   }
 }
];

const input = $('Evaluate Narrative Readiness').first().json || {};

return [
 {
   json: {
     schema_version: 'dalia.m11.narrative_rehearsal_result.v1',
     success: input.narrative_readiness?.go_no_go !== 'NO_GO_NARRATIVE',
     result_type: 'narrative_rehearsal_package_ready',

     narrative_rehearsal: {
       narrative_rehearsal_id: input.narrative_rehearsal?.narrative_rehearsal_id || '',
       demo_title: input.narrative_rehearsal?.demo_title || '',
       target_audience: input.narrative_rehearsal?.target_audience || '',
       narrative_goal: input.narrative_rehearsal?.narrative_goal || '',
       status: input.narrative_readiness?.status || '',
       go_no_go: input.narrative_readiness?.go_no_go || ''
     },

     package: {
       demo_script: input.demo_narrative_script || {},
       demo_scenes: input.demo_commercial_scenes || [],
       evaluation_criteria: input.narrative_evaluation_criteria || {},
       presenter_checklist: input.presenter_checklist || [],
       fallback_plan: input.demo_fallback_plan || []
     },

     findings: input.narrative_readiness?.findings || [],
     warnings: input.narrative_readiness?.warnings || [],
     adjustment_backlog: input.narrative_readiness?.adjustment_backlog || [],

     completed_at: new Date().toISOString()
   }
 }
];
